create table if not exists contas (id bigint generated by default as identity primary key, nome text, tipo text, categoria text, fornecedor_cliente text, valor numeric, emissao date, vencimento date, forma_pagamento text, status text default 'pendente', parcelas_info jsonb, created_at timestamp default now()); create table if not exists contatos (id bigint generated by default as identity primary key, nome text, tipo text, created_at timestamp default now()); alter table contas disable row level security; alter table contatos disable row level security;